const int maxn = 5e5 + 5;

struct Node {
    long long ls, lv, v;
    Node() : ls(0), lv(-1), v(0) {}
    Node(long long ls, long long lv, long long v) : ls(ls), lv(lv), v(v) {}
};
Node seg[4000005];
void propagate(int l, int r, int id) {
    if (seg[id].lv != -1) {
        seg[id * 2].lv = seg[id].lv;
        seg[id * 2 + 1].lv = seg[id].lv;
        seg[id * 2].v = seg[id].lv;
        seg[id * 2 + 1].v = seg[id].lv;
        seg[id * 2].ls = seg[id * 2 + 1].ls = 0;
        seg[id].lv = -1;
    }
    if (seg[id].ls != 0) {
        seg[id * 2].v += seg[id].ls;
        seg[id * 2 + 1].v += seg[id].ls;
        if (seg[id * 2].lv != -1) {
            seg[id * 2].lv += seg[id].ls;
        } else {
            seg[id * 2].ls += seg[id].ls;
        }
        if (seg[id * 2 + 1].lv != -1) {
            seg[id * 2 + 1].lv += seg[id].ls;
        } else {
            seg[id * 2 + 1].ls += seg[id].ls;
        }
        seg[id].ls = 0;
    }   
}
Node operator+(const Node &a, const Node &b) {
    Node c;
    c.v = max(a.v, b.v);
    c.ls = 0;
    c.lv = -1;
    return c;
}

void update1(int l, int r, int id, int ql, int qr, int v) {
    if(r < ql or qr < l) return;
    if(ql <= l and r <= qr) {
        seg[id].v += v;
        if (seg[id].lv != -1) seg[id].lv += v;
        else seg[id].ls += v;
        return;
    }
    propagate(l, r, id);
    int mid = (l + r) / 2;
    update1(l, mid, id * 2, ql, qr, v);
    update1(mid + 1, r, id * 2 + 1, ql, qr, v);
    seg[id] = seg[id * 2] + seg[id * 2  +1];
}
void update2(int l, int r, int id, int ql, int qr, int v) {
    if(r < ql or qr < l) return;
    if(ql <= l and r <= qr) {
        seg[id].v = v;
        seg[id].lv = v;
        seg[id].ls = 0;
        return;
    }
    propagate(l, r, id);
    int mid = (l + r) / 2;
    update2(l, mid, id * 2, ql, qr, v);
    update2(mid + 1, r, id * 2 + 1, ql, qr, v);
    seg[id] = seg[id * 2] + seg[id * 2  +1];
}
vector<tuple<int, int, bool>> queries[maxn];
int ans[maxn];

int main() {
    ios::sync_with_stdio(0); cin.tie(0);
    int n, m;
    cin >> n >> m;

    for (int i = 1; i <= m; i++) {
        int q, x, y;
        cin >> q >> x >> y;
        queries[q].push_back({x, y, 1});
    }

    for (int i = 1; i <= n; i++) {
        vector<pair<int, int>> ranges;
        ranges.reserve(queries[i].size());
        for (const auto &range : queries[i]) {
            ranges.push_back({get<0>(range), get<1>(range)});
        }
        sort(ranges.begin(), ranges.end());

        int next = 0;
        for (const auto &[l, r] : ranges) {
            if (l > next) {
                queries[i].push_back({next, l, 0});
            }
            next = max(next, r);
        }
        if (next < 1e9) {
            queries[i].push_back({next, 1e9, 0});
        }
    }

    vector<int> coords = {0, (int)1e9};
    for (int i = 1; i <= n; i++) {
        for (const auto &[l, r, t] : queries[i]) {
            coords.push_back(l);
            coords.push_back(r);
        }
    }
    sort(coords.begin(), coords.end());
    coords.erase(unique(coords.begin(), coords.end()), coords.end());

    int n_ = coords.size() - 1;
    for (int i = n; i >= 1; i--) {
        for (auto [x, y, t] : queries[i]) {
            int l = lower_bound(coords.begin(), coords.end(), x) - coords.begin() + 1;
            int r = lower_bound(coords.begin(), coords.end(), y) - coords.begin();
            if (l <= r) {
                (t ? update1 : update2)(1, n_, 1, l, r, t);
            }
        }
        ans[i] = seg[1].v;
    }

    for (int i = 1; i <= n; i++) {
        cout << ans[i] << '\n';
    }
}